// ------------------------------------------------------------------ render
(() => {
  const byId = Object.fromEntries(CHIP.map(c => [c.id, c]));
  const groups = [...new Set(CHIP.map(c => c.group))];
  const stColor = { decided: "var(--ok)", proposed: "var(--ff)", sketch: "var(--at)", open: "var(--muted)" };
  const idx = document.getElementById("chipIndex");
  const arts = document.getElementById("chipArticles");
  if (!idx || !arts) return;
  idx.innerHTML = groups.map(g => `<div><span class="lab">${g}</span>` +
    CHIP.filter(c => c.group === g).map(c => `<a href="#chip-${c.id}"><span>${c.title.split(":")[0]}</span><i class="dot" style="background:${stColor[c.status[0][0]]}" title="${c.status[0][1]}"></i></a>`).join("") + "</div>").join("");
  const list = (items) => `<ul>${items.map(i => `<li>${i}</li>`).join("")}</ul>`;
  arts.innerHTML = CHIP.map(c => `
    <article class="comp" id="chip-${c.id}">
      <div class="comp-head">
        <span class="eyebrow">${c.group}</span>
        <h3>${c.title}</h3>
        <div class="row">${c.status.map(([k, t]) => `<span class="pill st-${k}">${t}</span>`).join("")}<span class="refs">${c.refs}</span></div>
      </div>
      <div class="decision"><span class="lab">What we've decided</span>${c.decision}</div>
      <div class="block"><span class="lab">Why decide it now</span><p>${c.why}</p></div>
      <div class="two">
        <div class="block"><span class="lab">How it works</span>${list(c.how)}</div>
        <div class="block"><span class="lab">Key numbers</span><ul class="nums">${c.nums.map(([k, v]) => `<li>${k}<br><b>${v}</b></li>`).join("")}</ul></div>
      </div>
      <div class="block"><span class="lab">Model maths it performs</span>${list(c.computes)}</div>
      <div class="block"><span class="lab">Talks to</span><div class="talks">${c.talks.map(([id, how]) => `<a href="#chip-${id}">${byId[id] ? byId[id].title.split(":")[0] : id} <span class="how">· ${how}</span></a>`).join("")}</div></div>
      <div class="block"><span class="lab">Where it fits</span><p>${c.fits}</p></div>
      <div class="block alts"><span class="lab">Alternatives we didn't choose</span><ul>${c.alts.map(([o, w]) => `<li><b>${o}.</b> ${w}</li>`).join("")}</ul></div>
      <div class="block"><span class="lab">Still open</span>${list(c.open)}</div>
    </article>`).join("");
})();
